export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity, m = inputs.mass;
  const T = 2 * u / g, ta = u / g;
  const t = sdk.clamp(time, 0, T);
  const h = Math.max(0, u * t - g * t * t / 2);
  const v = u - g * t;
  const F = m * g;
  const top = u * u / (2 * g);
  let st = 'Rising';
  if (time <= 0) st = 'Ready to toss';
  else if (Math.abs(t - ta) < 0.005) st = 'At the top';
  else if (t >= T - 1e-9) st = 'Back at launch height';
  else if (t > ta) st = 'Falling';
  const o = [];
  o.push(...sdk.panel({ id: 'lane.motion', x: 10, y: 34, w: 305, h: 370, title: 'The motion', state: st }));
  o.push(...sdk.panel({ id: 'lane.graph', x: 325, y: 34, w: 305, h: 370, title: 'Velocity over time', state: 'v = u - g t' }));
  const yb = 380, yt = 80;
  const py = (y) => yb - (y / 2.2) * (yb - yt);
  o.push(sdk.axis('axis.h', { x: 70, y: yb, length: yb - yt, orientation: 'y', min: 0, max: 2.2, ticks: [0, 0.5, 1, 1.5, 2], label: 'Height', unit: 'm' }));
  const by = py(h);
  o.push(sdk.circle('ball.toss', 140, by, 26, {}));
  o.push(...sdk.vector('vec.v', { x: 140, y: by - 20 * 0 }, { value: v, direction: 'up' }, { scale: 12, label: 'v' }));
  o.push(...sdk.vector('vec.a', { x: 180, y: by }, { value: -g, direction: 'up' }, { scale: 5, label: 'a' }));
  o.push(...sdk.callout(205, 120, ['v = ' + sdk.format(v, 2) + ' m/s', 'a = ' + sdk.format(-g, 1) + ' m/s^2', 'Fg = ' + sdk.format(F, 1) + ' N'], { id: 'callout.toss' }));
  const pts = [];
  const n = 20;
  for (let i = 0; i <= n; i++) { const x = 1.8 * i / n; if (x <= t + 1e-9 || true) pts.push({ x, y: sdk.clamp(u - g * x, -5.5, 5.5) }); }
  const tr = [];
  const k = 12;
  for (let i = 0; i <= k; i++) { const x = t * i / k; tr.push({ x: Math.min(x, 1.8), y: sdk.clamp(u - g * x, -5.5, 5.5) }); }
  o.push(sdk.plot('plot.vt', { x: 345, y: 80, w: 275, h: 280, axes: { x: { label: 'Time', min: 0, max: 1.8, unit: 's' }, y: { label: 'Velocity', min: -5.5, max: 5.5, unit: 'm/s' } }, series: [{ label: 'v(t) trace', kind: 'line', points: tr.length > 1 ? tr : [{ x: 0, y: u }, { x: 0.001, y: u - g * 0.001 }] }, { label: 'v = u - g t', kind: 'line', points: pts }] }));
  o.push(sdk.text('plot.vt.note', 480, 395, 'slope a = -g', { align: 'middle' }));
  return { frame: { width: 640, height: 420, objects: o, readouts: [{ id: 'velocity', value: v }, { id: 'acceleration', value: -g }, { id: 'force', value: F }, { id: 'motionState', value: st }] }, quantities: { launchSpeed: u, gravity: g, mass: m, apexTime: ta, apexHeight: top, height: h, velocity: v, acceleration: -g, force: F, motionState: 0 } };
}
